var n=`1268-pernil`;var r=`world-1268`;var t=`PR`;var o=`central-america-caribbean`;var a=8;var s=356;var l={en:`Pernil`,ua:`Перніль`};var g={en:`Pernil is a dish from Puerto Rico featuring pork shoulder, garlic, orange juice, lime juice. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Перніль, страва кухні країни Пуерто-Рико з такими основними складниками: свиняча лопатка, часник, апельсиновий сік, сік лайма. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 180 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 180 хвилин.`,t:[`marinating`],m:180,i:[[`pork-shoulder`,1200,`g`],[`garlic`,8,`clove`],[`dried-oregano`,8,`g`],[`orange-juice`,160,`ml`],[`lime-juice`,80,`ml`]]},{en:`Roast in a preheated 190°C oven for about 165 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 165 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:165,i:[[`olive-oil`,65,`ml`]]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`red-onion`,140,`g`]]}];var u={slug:n,id:r,country:`PR`,region:o,servings:8,minutes:356,title:l,text:g,steps:d};export{t as country,u as default,r as id,s as minutes,o as region,a as servings,n as slug,d as steps,g as text,l as title};